export function validateTaxInput(rawInput: string | number): { value: number | null; error: string | null } {
  if (typeof rawInput === 'string') {
    const trimmed = rawInput.trim();
    if (trimmed === '') {
      return { value: null, error: 'Enter an amount' };
    }
    // Check if it contains characters that are not digits, commas, or decimal point
    // Note: If someone typed letters like "abc" or "100k"
    const sanitized = trimmed.replace(/,/g, '');
    if (!/^-?\d+(\.\d+)?$/.test(sanitized)) {
      return { value: null, error: 'Enter numbers only' };
    }
    const num = Number(sanitized);
    if (isNaN(num)) {
      return { value: null, error: 'Enter numbers only' };
    }
    return validateNumericBounds(num);
  }

  if (typeof rawInput === 'number') {
    if (isNaN(rawInput)) {
      return { value: null, error: 'Enter numbers only' };
    }
    return validateNumericBounds(rawInput);
  }

  return { value: null, error: 'Enter an amount' };
}

function validateNumericBounds(num: number): { value: number | null; error: string | null } {
  if (num < 0) {
    return { value: null, error: 'Amount cannot be negative' };
  }
  if (num === 0) {
    return { value: null, error: 'Amount must be greater than zero' };
  }
  if (num > TAX_CONFIG_FY2026_27.maxAllowedInput) {
    return { value: null, error: 'Amount is too large' };
  }
  return { value: num, error: null };
}

/**
 * Computes progressive slab-by-slab tax breakdown for salaried income.
 * Only slabs up to the income are listed. Slabs above income are excluded (S-2).
 */
export function computeSalariedBreakdown(
  annualIncome: number,
  slabs: TaxSlab[] = TAX_CONFIG_FY2026_27.salariedSlabs
): SlabBreakdownItem[] {
  const breakdown: SlabBreakdownItem[] = [];

  for (let i = 0; i < slabs.length; i++) {
    const slab = slabs[i];
    if (annualIncome <= slab.min) {
      break;
    }

    const slabCapacity = slab.max - slab.min;
    const isExceedingSlab = annualIncome > slab.max;
    const taxableInThisSlab = isExceedingSlab ? slabCapacity : annualIncome - slab.min;
    const taxInThisSlab = Math.round(taxableInThisSlab * slab.rate);

    let label = '';
    if (slab.min === 0) {
      label = `Rs ${taxInThisSlab.toLocaleString('en-US')} on the first Rs ${taxableInThisSlab.toLocaleString('en-US')}`;
    } else if (isExceedingSlab) {
      label = `Rs ${taxInThisSlab.toLocaleString('en-US')} on the next Rs ${taxableInThisSlab.toLocaleString('en-US')}`;
    } else {
      label = `Rs ${taxInThisSlab.toLocaleString('en-US')} on the remaining Rs ${taxableInThisSlab.toLocaleString('en-US')}`;
    }

    breakdown.push({
      slabIndex: i + 1,
      label,
      taxableAmount: taxableInThisSlab,
      rate: slab.rate,
      tax: taxInThisSlab,
    });
  }

  return breakdown;
}

/**
 * Calculates Salaried Employee tax liability from monthly salary.
 * Annual income = monthly salary * 12.
 */
export function calculateSalariedTax(
  monthlySalary: number,
  config: TaxConfig = TAX_CONFIG_FY2026_27
): SalariedCalculationResult {
  const annualSalary = monthlySalary * 12;

  // Find applicable slab
  let annualTax = 0;
  for (const slab of config.salariedSlabs) {
    if (annualSalary > slab.min && annualSalary <= slab.max) {
      const excess = annualSalary - slab.min;
      annualTax = slab.baseTax + excess * slab.rate;
      break;
    }
  }

  const roundedAnnualTax = Math.round(annualTax);
  const monthlyTax = Math.round(roundedAnnualTax / 12);
  const monthlyTakeHome = Math.round(monthlySalary - monthlyTax);
  const annualTakeHome = Math.round(annualSalary - roundedAnnualTax);
  const effectiveRate = annualSalary > 0 ? (roundedAnnualTax / annualSalary) * 100 : 0;
  const breakdown = computeSalariedBreakdown(annualSalary, config.salariedSlabs);

  return {
    monthlySalary,
    annualSalary,
    annualTax: roundedAnnualTax,
    monthlyTax,
    monthlyTakeHome,
    annualTakeHome,
    effectiveRate: Number(effectiveRate.toFixed(2)),
    breakdown,
    fiscalYear: config.fiscalYear,
  };
}

/**
 * Calculates Businessman / Sole Proprietor tax liability from annual net business profit.
 * Applies 10% surcharge if net profit strictly exceeds Rs 10,000,000.
 * S-6: Monthly savings amount is annual tax divided by 12, rounded up to next whole rupee (Math.ceil).
 */
export function calculateBusinessTax(
  annualProfit: number,
  config: TaxConfig = TAX_CONFIG_FY2026_27
): BusinessCalculationResult {
  let baseTax = 0;

  for (const slab of config.businessSlabs) {
    if (annualProfit > slab.min && annualProfit <= slab.max) {
      const excess = annualProfit - slab.min;
      baseTax = slab.baseTax + excess * slab.rate;
      break;
    }
  }

  const roundedBaseTax = Math.round(baseTax);

  let surcharge = 0;
  if (annualProfit > config.businessSurchargeThreshold) {
    surcharge = Math.round(roundedBaseTax * config.businessSurchargeRate);
  }

  const totalTax = roundedBaseTax + surcharge;
  const monthlySavingsAmount = totalTax > 0 ? Math.ceil(totalTax / 12) : 0;
  const effectiveRate = annualProfit > 0 ? (totalTax / annualProfit) * 100 : 0;

  return {
    annualProfit,
    baseTax: roundedBaseTax,
    surcharge,
    totalTax,
    monthlySavingsAmount,
    effectiveRate: Number(effectiveRate.toFixed(2)),
    isEstimate: true,
    fiscalYear: config.fiscalYear,
  };
}

