import { SlabTier } from './types.ts';

export const FISCAL_YEAR = 'FY 2026-27';
export const SALARIED_SOURCE_CITE = 'Finance Act 2026 (FBR), effective 1 July 2026';
export const BUSINESS_SOURCE_CITE = 'Finance Act 2026 / First Schedule, Income Tax Ordinance 2001';

export const SALARIED_SLABS: SlabTier[] = [
