];

export const BUSINESS_SURCHARGE_THRESHOLD = 10000000;
export const BUSINESS_SURCHARGE_RATE_PERCENT = 10;
export const MAX_ALLOWED_AMOUNT = 1000000000; // Rs 1,000,000,000 (1 Billion)

import { MAX_ALLOWED_AMOUNT } from './slabs.ts';
import { ValidationResult } from './types.ts';

export function validateTaxInput(rawInput: string | number | null | undefined): ValidationResult {
  if (rawInput === null || rawInput === undefined) {
    return { isValid: false, error: 'Enter an amount' };
  }

  const str = String(rawInput).trim();

  if (str === '') {
    return { isValid: false, error: 'Enter an amount' };
  }

  // Check for letters
  if (/[a-zA-Z]/.test(str)) {
    return { isValid: false, error: 'Enter numbers only' };
  }

  // Check for negative numbers before comma replacement
  if (str.startsWith('-')) {
    return { isValid: false, error: 'Amount cannot be negative' };
  }

  // Remove commas for standard currency input support
  const sanitized = str.replace(/,/g, '');

  const num = Number(sanitized);

  if (isNaN(num)) {
    return { isValid: false, error: 'Enter numbers only' };
  }

  if (num < 0) {
    return { isValid: false, error: 'Amount cannot be negative' };
  }

  if (num === 0) {
    return { isValid: false, error: 'Amount must be greater than zero' };
  }

  if (num > MAX_ALLOWED_AMOUNT) {
    return { isValid: false, error: 'Amount is too large' };
  }

  return { isValid: true, value: num };
}

{
  "name": "pakistan-income-tax-calculator",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
