}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
});

import {
  SALARIED_CONFIG,
  BUSINESS_CONFIG,
  MAX_ALLOWED_AMOUNT,
} from '../config/taxSlabs.js';

/**
 * Validates tax input according to Story S-3
 * @param {string|number|null|undefined} rawInput
 * @returns {{ isValid: boolean, error?: string, value?: number }}
 */
export function validateTaxInput(rawInput) {
  if (rawInput === null || rawInput === undefined) {
    return { isValid: false, error: 'Enter an amount' };
  }

  const str = String(rawInput).trim();

  if (str === '') {
    return { isValid: false, error: 'Enter an amount' };
  }

  // Check for alphabetical characters
  if (/[a-zA-Z]/.test(str)) {
    return { isValid: false, error: 'Enter numbers only' };
  }

  // Check for negative number
  if (str.startsWith('-')) {
    return { isValid: false, error: 'Amount cannot be negative' };
  }

  // Strip standard commas
  const sanitized = str.replace(/,/g, '');
  const num = Number(sanitized);

  if (isNaN(num)) {
    return { isValid: false, error: 'Enter numbers only' };
  }

  if (num < 0) {
    return { isValid: false, error: 'Amount cannot be negative' };
  }

  if (num === 0) {
    return { isValid: false, error: 'Amount must be greater than zero' };
  }

  if (num > MAX_ALLOWED_AMOUNT) {
    return { isValid: false, error: 'Amount is too large' };
  }

  return { isValid: true, value: num };
}

/**
 * Calculates progressive slab-by-slab breakdown
 * @param {number} income
 * @param {Array} slabs
 * @returns {Array} List of slab breakdown items up to the active slab
 */
export function calculateSlabBreakdown(income, slabs) {
  const breakdown = [];

  for (let i = 0; i < slabs.length; i++) {
    const slab = slabs[i];
    const isFirstSlab = slab.minIncome === 0;
    const slabCap = slab.maxIncome;

    if (income <= slab.minIncome) {
      break;
    }

    const taxableChunk = slabCap !== null
      ? Math.min(income, slabCap) - slab.minIncome
      : income - slab.minIncome;

    const taxForChunk = Math.round((taxableChunk * slab.ratePercent) / 100);

    let slabRangeText = '';
    const isRemaining = (slabCap === null || income < slabCap) && !isFirstSlab;

    if (isFirstSlab) {
      slabRangeText = `the first Rs ${slabCap.toLocaleString()}`;
    } else if (isRemaining) {
      slabRangeText = `the remaining Rs ${taxableChunk.toLocaleString()}`;
    } else {
      slabRangeText = `the next Rs ${taxableChunk.toLocaleString()}`;
    }

    breakdown.push({
      slabNumber: slab.slabNumber,
      label: slab.label,
      ratePercent: slab.ratePercent,
      taxableAmount: taxableChunk,
      tax: taxForChunk,
      description: `Rs ${taxForChunk.toLocaleString()} on ${slabRangeText}`,
    });

    if (slabCap !== null && income <= slabCap) {
      break;
    }
  }

  return breakdown;
}

/**
 * Pure calculation for Salaried Employee (S-1, S-2, S-4)
 * @param {number} monthlySalary
 * @returns {object} Salaried tax details
 */
export function calculateSalariedTax(monthlySalary) {
  const annualSalary = monthlySalary * 12;
  const slabs = SALARIED_CONFIG.slabs;

  let activeSlab = slabs[0];
  for (const slab of slabs) {
    if (annualSalary > slab.minIncome) {
      activeSlab = slab;
    }
  }

  let rawAnnualTax = 0;
  if (annualSalary > activeSlab.minIncome && activeSlab.ratePercent > 0) {
    const excess = annualSalary - activeSlab.minIncome;
    rawAnnualTax = activeSlab.baseTax + (excess * (activeSlab.ratePercent / 100));
  } else {
    rawAnnualTax = activeSlab.baseTax;
  }

  // Rounded to nearest whole rupee per S-1
  const annualTax = Math.round(rawAnnualTax);
  const monthlyTax = Math.round(annualTax / 12);
  const monthlyTakeHome = Math.round(monthlySalary - monthlyTax);
  const annualTakeHome = Math.round(annualSalary - annualTax);
  const effectiveTaxRate = annualSalary > 0 ? (annualTax / annualSalary) * 100 : 0;

  const slabBreakdown = calculateSlabBreakdown(annualSalary, slabs);

  return {
    monthlySalary,
    annualSalary,
    annualTax,
    monthlyTax,
    monthlyTakeHome,
    annualTakeHome,
    effectiveTaxRate: Number(effectiveTaxRate.toFixed(2)),
    activeSlab,
    slabBreakdown,
    fiscalYear: SALARIED_CONFIG.fiscalYear,
    sourceCite: SALARIED_CONFIG.sourceCite,
  };
}

/**
 * Pure calculation for Businessman / Sole Proprietor (S-5, S-6)
 * @param {number} annualProfit
 * @returns {object} Business tax details
 */
export function calculateBusinessTax(annualProfit) {
  const slabs = BUSINESS_CONFIG.slabs;

  let activeSlab = slabs[0];
  for (const slab of slabs) {
    if (annualProfit > slab.minIncome) {
      activeSlab = slab;
    }
  }

  let rawBaseTax = 0;
  if (annualProfit > activeSlab.minIncome && activeSlab.ratePercent > 0) {
    const excess = annualProfit - activeSlab.minIncome;
    rawBaseTax = activeSlab.baseTax + (excess * (activeSlab.ratePercent / 100));
  } else {
    rawBaseTax = activeSlab.baseTax;
  }

  const baseTax = Math.round(rawBaseTax);

  // Surcharge: if annual taxable profit is strictly above 10,000,000, add 10% of the tax
  const hasSurcharge = annualProfit > BUSINESS_CONFIG.surchargeThreshold;
  const surcharge = hasSurcharge
    ? Math.round(baseTax * (BUSINESS_CONFIG.surchargeRatePercent / 100))
    : 0;

  const totalAnnualTax = baseTax + surcharge;

  // Monthly set-aside per S-6: annual tax divided by 12, rounded up to next whole rupee
  const monthlySavingsAmount = totalAnnualTax > 0 ? Math.ceil(totalAnnualTax / 12) : 0;

  const effectiveTaxRate = annualProfit > 0 ? (totalAnnualTax / annualProfit) * 100 : 0;
  const slabBreakdown = calculateSlabBreakdown(annualProfit, slabs);

  return {
    annualProfit,
    baseTax,
    surcharge,
    hasSurcharge,
    totalAnnualTax,
    monthlySavingsAmount,
    effectiveTaxRate: Number(effectiveTaxRate.toFixed(2)),
    activeSlab,
    slabBreakdown,
    isEstimate: true,
    fiscalYear: BUSINESS_CONFIG.fiscalYear,
    sourceCite: BUSINESS_CONFIG.sourceCite,
  };
}

import { describe, it, expect } from 'vitest';
import {
  validateTaxInput,
  calculateSalariedTax,
  calculateBusinessTax,
  calculateSlabBreakdown,
} from '../src/utils/taxCalculator.js';
import { SALARIED_CONFIG, BUSINESS_CONFIG } from '../src/config/taxSlabs.js';

describe('Story S-3: Input Validation and Error Handling', () => {
  it('rejects empty input with "Enter an amount"', () => {
    expect(validateTaxInput('')).toEqual({ isValid: false, error: 'Enter an amount' });
    expect(validateTaxInput('   ')).toEqual({ isValid: false, error: 'Enter an amount' });
    expect(validateTaxInput(null)).toEqual({ isValid: false, error: 'Enter an amount' });
    expect(validateTaxInput(undefined)).toEqual({ isValid: false, error: 'Enter an amount' });
  });

  it('rejects letters and non-numeric characters with "Enter numbers only"', () => {
    expect(validateTaxInput('abc')).toEqual({ isValid: false, error: 'Enter numbers only' });
    expect(validateTaxInput('100k')).toEqual({ isValid: false, error: 'Enter numbers only' });
    expect(validateTaxInput('salary')).toEqual({ isValid: false, error: 'Enter numbers only' });
    expect(validateTaxInput('12.34.56')).toEqual({ isValid: false, error: 'Enter numbers only' });
  });

  it('rejects negative numbers with "Amount cannot be negative"', () => {
    expect(validateTaxInput('-1')).toEqual({ isValid: false, error: 'Amount cannot be negative' });
    expect(validateTaxInput('-50000')).toEqual({ isValid: false, error: 'Amount cannot be negative' });
    expect(validateTaxInput('-100000')).toEqual({ isValid: false, error: 'Amount cannot be negative' });
  });

  it('rejects zero with "Amount must be greater than zero"', () => {
    expect(validateTaxInput('0')).toEqual({ isValid: false, error: 'Amount must be greater than zero' });
    expect(validateTaxInput(0)).toEqual({ isValid: false, error: 'Amount must be greater than zero' });
    expect(validateTaxInput('-0')).toEqual({ isValid: false, error: 'Amount must be greater than zero' });
  });

  it('rejects amounts greater than Rs 1,000,000,000 with "Amount is too large"', () => {
    expect(validateTaxInput('1000000001')).toEqual({ isValid: false, error: 'Amount is too large' });
    expect(validateTaxInput('5000000000')).toEqual({ isValid: false, error: 'Amount is too large' });
  });

  it('accepts valid amounts including comma-formatted numbers', () => {
    expect(validateTaxInput('100000')).toEqual({ isValid: true, value: 100000 });
    expect(validateTaxInput('100,000')).toEqual({ isValid: true, value: 100000 });
    expect(validateTaxInput('1,000,000,000')).toEqual({ isValid: true, value: 1000000000 });
    expect(validateTaxInput(200000)).toEqual({ isValid: true, value: 200000 });
  });
});

describe('Story S-1: Salaried Employee Calculations', () => {
  it('calculates monthly Rs 50,000 (annual Rs 600,000): tax is Rs 0, take-home is Rs 50,000', () => {
    const result = calculateSalariedTax(50000);
    expect(result.annualSalary).toBe(600000);
    expect(result.annualTax).toBe(0);
    expect(result.monthlyTax).toBe(0);
    expect(result.monthlyTakeHome).toBe(50000);
    expect(result.annualTakeHome).toBe(600000);
    expect(result.effectiveTaxRate).toBe(0);
  });

  it('calculates monthly Rs 100,000: annual tax Rs 6,000, monthly tax Rs 500, take-home Rs 99,500', () => {
    const result = calculateSalariedTax(100000);
    expect(result.annualSalary).toBe(1200000);
    expect(result.annualTax).toBe(6000);
    expect(result.monthlyTax).toBe(500);
    expect(result.monthlyTakeHome).toBe(99500);
    expect(result.annualTakeHome).toBe(1194000);
    expect(result.effectiveTaxRate).toBe(0.5);
  });

  it('calculates monthly Rs 200,000: annual tax Rs 156,000, monthly tax Rs 13,000, take-home Rs 187,000', () => {
    const result = calculateSalariedTax(200000);
    expect(result.annualSalary).toBe(2400000);
    expect(result.annualTax).toBe(156000);
    expect(result.monthlyTax).toBe(13000);
    expect(result.monthlyTakeHome).toBe(187000);
    expect(result.annualTakeHome).toBe(2244000);
    expect(result.effectiveTaxRate).toBe(6.5);
  });

  it('calculates monthly Rs 1,000,000: annual tax Rs 3,174,000, monthly tax Rs 264,500, take-home Rs 735,500', () => {
    const result = calculateSalariedTax(1000000);
    expect(result.annualSalary).toBe(12000000);
    expect(result.annualTax).toBe(3174000);
    expect(result.monthlyTax).toBe(264500);
    expect(result.monthlyTakeHome).toBe(735500);
    expect(result.annualTakeHome).toBe(8826000);
  });

  it('rounds amounts that leave a fraction of a rupee to the nearest whole rupee', () => {
    // 65,000 * 12 = 780,000 -> 1% of (780,000 - 600,000) = 1,800 annual tax -> 150/mo
    // Let's test an amount that produces fractional monthly tax:
    // monthly 60,005 -> annual 720,060 -> tax = 1% of 120,060 = 1,200.6 -> round to 1,201
    // monthly tax = 1201 / 12 = 100.083 -> round to 100
    const result = calculateSalariedTax(60005);
    expect(result.annualTax).toBe(1201);
    expect(result.monthlyTax).toBe(100);
