.breakdown-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: none;
  padding: 10px 0;
  font-size: 1rem;
  font-weight: 600;
  color: #1e293b;
  cursor: pointer;
}

.breakdown-list {
  list-style: none;
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.breakdown-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #f8fafc;
  border: 1px solid var(--border-color);
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 0.9rem;
}

.breakdown-slab-desc {
  color: #334155;
  font-weight: 500;
}

.breakdown-slab-tax {
  font-weight: 700;
  color: #0f172a;
}

/* Slab Reference Table Modal / Card */
.slab-reference-section {
  margin-top: 32px;
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
}

.reference-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 8px;
}

.reference-header h3 {
  font-size: 1.15rem;
  font-weight: 700;
  color: #0f172a;
}

.reference-source {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.tax-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
  text-align: left;
}

.tax-table th {
  background: #f1f5f9;
  padding: 10px 12px;
  font-weight: 600;
  color: #334155;
  border-bottom: 2px solid var(--border-color);
}

.tax-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-color);
  color: #1e293b;
}

.tax-table tr:hover {
  background: #f8fafc;
}

.table-wrapper {
  overflow-x: auto;
}

/* Footer */
.app-footer {
  text-align: center;
  margin-top: 48px;
  font-size: 0.825rem;
  color: var(--text-muted);
}

@media (max-width: 640px) {
  .app-header h1 {
    font-size: 1.5rem;
  }
  .role-tabs {
    grid-template-columns: 1fr;
  }
  .calc-card {
    padding: 18px;
  }
}

import React from 'react';
import { Calendar, FileText } from 'lucide-react';
import { FISCAL_YEAR } from '../config/taxSlabs.js';

export default function Header({ showSlabModal, setShowSlabModal }) {
  return (
    <header className="app-header">
      <div className="header-badge">
        <Calendar size={14} />
        <span>{FISCAL_YEAR} Official Tax Rates</span>
      </div>
      <h1>Pakistan Income Tax Calculator</h1>
      <p>Compute personal income tax for Salaried Employees and Business Sole Proprietors</p>

      <div className="header-actions">
        <button
          type="button"
          className="btn-secondary"
          onClick={() => setShowSlabModal((prev) => !prev)}
          aria-label="View official tax slab tables"
        >
          <FileText size={16} />
          <span>{showSlabModal ? 'Hide Tax Slabs Table' : 'View FY 2026-27 Tax Slabs'}</span>
        </button>
      </div>
    </header>
  );
}

import React from 'react';
import { Briefcase, Building2 } from 'lucide-react';

export default function RoleTabs({ activeRole, onRoleChange }) {
  return (
    <nav className="role-tabs" aria-label="Calculator Role Selection">
      <button
        type="button"
        className={`tab-btn salaried-tab ${activeRole === 'salaried' ? 'active' : ''}`}
