import React, { useState } from 'react';
import { Calculator, AlertCircle, ChevronDown, ChevronUp, Info } from 'lucide-react';
import { validateTaxInput, calculateSalariedTax } from '../utils/taxCalculator.js';
import { FISCAL_YEAR, SALARIED_CONFIG } from '../config/taxSlabs.js';

export default function SalariedCalculator() {
  const [monthlyInput, setMonthlyInput] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [result, setResult] = useState(null);
  const [showBreakdown, setShowBreakdown] = useState(true);

  const handleCalculate = (e) => {
    if (e) e.preventDefault();

    const validation = validateTaxInput(monthlyInput);
    if (!validation.isValid) {
      setErrorMessage(validation.error);
      setResult(null);
      return;
    }

    setErrorMessage('');
    const taxData = calculateSalariedTax(validation.value);
    setResult(taxData);
  };

  const handleInputChange = (e) => {
    setMonthlyInput(e.target.value);
  };

  return (
    <div className="calc-card" data-testid="salaried-calculator">
      <div className="role-info-banner">
        <strong>Salaried Employee:</strong> For individuals on a fixed monthly salary with taxes withheld by employers under {FISCAL_YEAR}. 
        <em> (Source: {SALARIED_CONFIG.sourceCite})</em>
      </div>

      <form className="input-form" onSubmit={handleCalculate} noValidate>
        <div className="form-group">
          <label htmlFor="salaried-monthly-input">Monthly Gross Salary (Rs.)</label>
          <div className="input-wrapper">
            <span className="currency-prefix">Rs</span>
            <input
              id="salaried-monthly-input"
              type="text"
              className={`tax-input ${errorMessage ? 'input-error' : ''}`}
              placeholder="e.g. 100,000"
              value={monthlyInput}
              onChange={handleInputChange}
              aria-invalid={Boolean(errorMessage)}
              aria-describedby={errorMessage ? 'salaried-error' : 'salaried-hint'}
            />
          </div>
          <span id="salaried-hint" className="input-hint">
            Annual taxable income is calculated as monthly salary × 12.
          </span>
        </div>

        {errorMessage && (
          <div id="salaried-error" className="error-alert" role="alert">
            <AlertCircle size={18} />
            <span>{errorMessage}</span>
          </div>
        )}

        <button type="submit" className="btn-primary" id="salaried-calc-btn">
          <Calculator size={18} />
          <span>Calculate Tax</span>
        </button>
      </form>

      {result && (
        <div className="results-container" data-testid="salaried-results">
          <div className="stat-grid">
            <div className="stat-card highlight">
              <div className="stat-title">Monthly Take-Home Pay</div>
              <div className="stat-value">Rs {result.monthlyTakeHome.toLocaleString()}</div>
              <div className="stat-sub">After monthly tax withholding</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Monthly Tax</div>
              <div className="stat-value">Rs {result.monthlyTax.toLocaleString()}</div>
              <div className="stat-sub">Deducted from monthly salary</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Annual Tax</div>
              <div className="stat-value">Rs {result.annualTax.toLocaleString()}</div>
              <div className="stat-sub">Total tax for {FISCAL_YEAR}</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Annual Take-Home</div>
              <div className="stat-value">Rs {result.annualTakeHome.toLocaleString()}</div>
              <div className="stat-sub">Annual gross: Rs {result.annualSalary.toLocaleString()}</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Effective Tax Rate</div>
              <div className="stat-value">{result.effectiveTaxRate.toFixed(2)}%</div>
              <div className="stat-sub">Average tax rate across income</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Applicable Slab</div>
              <div className="stat-value">Slab #{result.activeSlab.slabNumber}</div>
              <div className="stat-sub">{result.activeSlab.label}</div>
            </div>
          </div>

          <div className="breakdown-section">
            <button
              type="button"
              className="breakdown-toggle"
              onClick={() => setShowBreakdown((prev) => !prev)}
              aria-expanded={showBreakdown}
            >
              <span>Tax Breakdown (Slab-by-Slab)</span>
              {showBreakdown ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
            </button>

            {showBreakdown && (
              <ul className="breakdown-list">
                {result.slabBreakdown.map((item) => (
                  <li key={item.slabNumber} className="breakdown-item">
                    <span className="breakdown-slab-desc">{item.description}</span>
                    <span className="breakdown-slab-tax">
                      {item.ratePercent > 0 ? `(${item.ratePercent}%)` : '(Exempt)'}
                    </span>
                  </li>
                ))}
                <li className="breakdown-item" style={{ background: '#f1f5f9', fontWeight: 700 }}>
                  <span>Total Annual Tax:</span>
                  <span>Rs {result.annualTax.toLocaleString()}</span>
                </li>
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Calculator, AlertCircle, ChevronDown, ChevronUp, AlertTriangle } from 'lucide-react';
import { validateTaxInput, calculateBusinessTax } from '../utils/taxCalculator.js';
import { FISCAL_YEAR, BUSINESS_CONFIG } from '../config/taxSlabs.js';

export default function BusinessCalculator() {
  const [profitInput, setProfitInput] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [result, setResult] = useState(null);
  const [showBreakdown, setShowBreakdown] = useState(true);

  const handleCalculate = (e) => {
    if (e) e.preventDefault();

    const validation = validateTaxInput(profitInput);
    if (!validation.isValid) {
      setErrorMessage(validation.error);
      setResult(null);
      return;
    }

    setErrorMessage('');
    const taxData = calculateBusinessTax(validation.value);
    setResult(taxData);
  };

  const handleInputChange = (e) => {
    setProfitInput(e.target.value);
  };

  return (
    <div className="calc-card" data-testid="business-calculator">
      <div className="role-info-banner business-theme">
        <strong>Businessman (Sole Proprietor):</strong> For unincorporated small business owners paying tax on annual net profit under {FISCAL_YEAR}. 
        <em> (Source: {BUSINESS_CONFIG.sourceCite})</em>
      </div>

      <form className="input-form" onSubmit={handleCalculate} noValidate>
        <div className="form-group">
          <label htmlFor="business-profit-input">Expected Annual Net Profit (Rs.)</label>
          <div className="input-wrapper">
            <span className="currency-prefix">Rs</span>
            <input
              id="business-profit-input"
              type="text"
              className={`tax-input ${errorMessage ? 'input-error' : ''}`}
              placeholder="e.g. 3,000,000"
              value={profitInput}
              onChange={handleInputChange}
              aria-invalid={Boolean(errorMessage)}
              aria-describedby={errorMessage ? 'business-error' : 'business-hint'}
            />
          </div>
          <span id="business-hint" className="input-hint">
            Taxable income is net business profit (gross revenue minus allowable expenses), not total sales.
          </span>
        </div>

        {errorMessage && (
          <div id="business-error" className="error-alert" role="alert">
            <AlertCircle size={18} />
            <span>{errorMessage}</span>
          </div>
        )}

        <button type="submit" className="btn-primary business-btn" id="business-calc-btn">
          <Calculator size={18} />
          <span>Calculate Estimated Tax</span>
        </button>
      </form>

      {result && (
        <div className="results-container" data-testid="business-results">
          {/* S-5: Clearly labeled as an estimate and not a final tax liability */}
          <div className="estimate-notice" role="note">
            <AlertTriangle size={18} />
            <span>
              <strong>Notice:</strong> This calculation is an <strong>estimate</strong> of your annual tax liability under {FISCAL_YEAR} sole proprietor slabs. It is not an official or final tax assessment.
            </span>
          </div>

          <div className="stat-grid">
            <div className="stat-card highlight business-highlight">
              <div className="stat-title">Monthly Amount to Set Aside</div>
              <div className="stat-value">Rs {result.monthlySavingsAmount.toLocaleString()}</div>
              <div className="stat-sub">Recommended monthly tax reserve (rounded up)</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Estimated Annual Tax</div>
              <div className="stat-value">Rs {result.totalAnnualTax.toLocaleString()}</div>
              <div className="stat-sub">Total payable for {FISCAL_YEAR}</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Base Tax (Before Surcharge)</div>
              <div className="stat-value">Rs {result.baseTax.toLocaleString()}</div>
              <div className="stat-sub">Progressive slab tax</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">High-Income Surcharge</div>
              <div className="stat-value">
                {result.hasSurcharge ? `Rs ${result.surcharge.toLocaleString()}` : 'Rs 0'}
              </div>
              <div className="stat-sub">
                {result.hasSurcharge ? '10% on tax (Profit > Rs 10M)' : 'Not applicable (≤ Rs 10M)'}
              </div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Effective Tax Rate</div>
              <div className="stat-value">{result.effectiveTaxRate.toFixed(2)}%</div>
              <div className="stat-sub">Tax as % of net profit</div>
            </div>

            <div className="stat-card">
              <div className="stat-title">Applicable Slab</div>
              <div className="stat-value">Slab #{result.activeSlab.slabNumber}</div>
              <div className="stat-sub">{result.activeSlab.label}</div>
            </div>
          </div>

          {result.hasSurcharge && (
            <div className="surcharge-card">
              <div className="surcharge-info">
                <h4>High-Income Surcharge Applied (+10% on tax)</h4>
                <p>Taxable profit exceeds Rs 10,000,000. Statutory 10% surcharge added to base tax.</p>
              </div>
              <div className="surcharge-amount">+ Rs {result.surcharge.toLocaleString()}</div>
            </div>
          )}

          <div className="breakdown-section">
            <button
              type="button"
              className="breakdown-toggle"
              onClick={() => setShowBreakdown((prev) => !prev)}
              aria-expanded={showBreakdown}
            >
              <span>Tax Breakdown (Slab-by-Slab)</span>
              {showBreakdown ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
            </button>

            {showBreakdown && (
              <ul className="breakdown-list">
                {result.slabBreakdown.map((item) => (
                  <li key={item.slabNumber} className="breakdown-item">
                    <span className="breakdown-slab-desc">{item.description}</span>
                    <span className="breakdown-slab-tax">
                      {item.ratePercent > 0 ? `(${item.ratePercent}%)` : '(Exempt)'}
                    </span>
                  </li>
                ))}

                {result.hasSurcharge && (
                  <li className="breakdown-item" style={{ background: '#faf5ff', color: '#6b21a8' }}>
                    <span className="breakdown-slab-desc">High-Income Surcharge (10% of base tax)</span>
                    <span className="breakdown-slab-tax">+ Rs {result.surcharge.toLocaleString()}</span>
                  </li>
                )}

                <li className="breakdown-item" style={{ background: '#f1f5f9', fontWeight: 700 }}>
                  <span>Total Estimated Tax:</span>
                  <span>Rs {result.totalAnnualTax.toLocaleString()}</span>
                </li>
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { SALARIED_CONFIG, BUSINESS_CONFIG, FISCAL_YEAR } from '../config/taxSlabs.js';

export default function SlabReferenceTable() {
  const [selectedTab, setSelectedTab] = useState('salaried');

  const currentConfig = selectedTab === 'salaried' ? SALARIED_CONFIG : BUSINESS_CONFIG;

  return (
    <section className="slab-reference-section" aria-labelledby="slab-table-title">
      <div className="reference-header">
        <div>
          <h3 id="slab-table-title">Official Income Tax Slabs ({FISCAL_YEAR})</h3>
          <p className="reference-source">
            <strong>Legal Source:</strong> {currentConfig.sourceCite}
          </p>
          {selectedTab === 'salaried' && (
            <p className="reference-source" style={{ color: '#0f766e', marginTop: '2px' }}>
              ✓ Note: 9% high-income surcharge on salaried individuals is abolished.
            </p>
          )}
          {selectedTab === 'businessman' && (
            <p className="reference-source" style={{ color: '#7c3aed', marginTop: '2px' }}>
              ✓ Note: 10% tax surcharge applies if taxable profit exceeds Rs 10,000,000.
            </p>
          )}
        </div>

        <div style={{ display: 'flex', gap: '8px' }}>
          <button
            type="button"
            className={`btn-secondary ${selectedTab === 'salaried' ? 'active' : ''}`}
            style={selectedTab === 'salaried' ? { background: '#0284c7', color: '#fff', borderColor: '#0284c7' } : {}}
            onClick={() => setSelectedTab('salaried')}
          >
            Salaried Slabs
          </button>
          <button
            type="button"
            className={`btn-secondary ${selectedTab === 'businessman' ? 'active' : ''}`}
            style={selectedTab === 'businessman' ? { background: '#7c3aed', color: '#fff', borderColor: '#7c3aed' } : {}}
            onClick={() => setSelectedTab('businessman')}
          >
            Business Slabs
          </button>
        </div>
      </div>

      <div className="table-wrapper">
        <table className="tax-table">
          <thead>
            <tr>
              <th style={{ width: '80px' }}>Slab #</th>
              <th>Taxable Income Bracket (Rs.)</th>
              <th>Rate of Tax</th>
            </tr>
          </thead>
          <tbody>
            {currentConfig.slabs.map((slab) => (
              <tr key={slab.slabNumber}>
                <td><strong>#{slab.slabNumber}</strong></td>
                <td>{slab.label}</td>
                <td>{slab.ruleDescription}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </section>
  );
}

import React, { useState } from 'react';
import Header from './components/Header.jsx';
import RoleTabs from './components/RoleTabs.jsx';
import SalariedCalculator from './components/SalariedCalculator.jsx';
