import fs from 'fs';
import readline from 'readline';

const logPath = '[system-path]';

async function generateTranscript() {
  const fileStream = fs.createReadStream(logPath);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  let out = '# Session Transcript: Pakistan Income Tax Calculator Web App\n\n';
  out += '**Session ID:** `619e8df5-7bcd-426d-acbe-1db8269aaa53`  \n';
  out += '**AI Tool:** Antigravity (Google DeepMind)  \n';
  out += '**Model:** Gemini 3.8 Flash  \n\n---\n\n';

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const data = JSON.parse(line);
      if (data.type === 'USER_INPUT' && data.content) {
        let clean = data.content;
        const match = clean.match(/<USER_REQUEST>([\s\S]*?)<\/USER_REQUEST>/);
        if (match) {
          clean = match[1].trim();
        } else {
          clean = clean
            .replace(/<ADDITIONAL_METADATA>[\s\S]*?<\/ADDITIONAL_METADATA>/g, '')
            .replace(/<USER_SETTINGS_CHANGE>[\s\S]*?<\/USER_SETTINGS_CHANGE>/g, '')
            .trim();
        }
        if (clean) {
          out += `## User\n\n${clean}\n\n---\n\n`;
        }
      } else if (data.type === 'PLANNER_RESPONSE' && data.content) {
        out += `## Assistant\n\n${data.content.trim()}\n\n---\n\n`;
      }
    } catch (e) {}
  }

  fs.writeFileSync('transcripts/session-01.md', out, 'utf8');
}

generateTranscript();

