// Replace file:/// URL schemes with simple relative paths
content = content.replace(/file:\/\/\/[A-Za-z]:\/[^\)]+/g, (match) => {
  // extract relative path from the project root if present
  const idx = match.toLowerCase().indexOf('muhammad-attique-calculator/');
  if (idx !== -1) {
    return match.substring(idx + 'muhammad-attique-calculator/'.length);
  }
  return '[local-path]';
});

// Replace Windows drive paths ([system-path]\E Drive\...)
// [system-path]\...
content = content.replace(/[A-Za-z]:\\[Uu]sers\\[^\\]+\\[^\n`"'\s\)]+/g, '[system-path]');
content = content.replace(/[A-Za-z]:\/[Uu]sers\/[^\/]+\/[^\n`"'\s\)]+/g, '[system-path]');

// d:\E Drive\PPS\Muhammad-Attique-Calculator\...
