import fs from 'fs';
import readline from 'readline';

const srcLogPath = '[system-path]';
const destJsonlPath = 'transcripts/transcript_full.jsonl';
const destMdPath = 'transcripts/session-01.md';

function sanitizeText(str) {
  if (!str) return '';
  let res = str;
  // file:/// URLs
  res = res.replace(/file:\/\/\/[A-Za-z]:\/[^\)]+/g, (match) => {
    const idx = match.toLowerCase().indexOf('muhammad-attique-calculator/');
    if (idx !== -1) {
      return match.substring(idx + 'muhammad-attique-calculator/'.length);
    }
    return '[local-path]';
  });

  // Windows User paths
  res = res.replace(/[A-Za-z]:\\[Uu]sers\\[^\\]+\\[^\n`"'\s\)]+/g, '[system-path]');
  res = res.replace(/[A-Za-z]:\/[Uu]sers\/[^\/]+\/[^\n`"'\s\)]+/g, '[system-path]');
  res = res.replace(/C:\\\\Users\\\\[^\\]+\\\\/gi, '[system-path]\\\\');

  // Specific username
  res = res.replace(/[user]/gi, '[user]');

  // Project absolute paths
  res = res.replace(/[A-Za-z]:\\[^\\`"'\n]+\\[^\\`"'\n]+\\Muhammad-Attique-Calculator\\/gi, '');
  res = res.replace(/[A-Za-z]:\/[^\/`"'\n]+\/[^\/`"'\n]+\/Muhammad-Attique-Calculator\//gi, '');
  res = res.replace(/[A-Za-z]:\\[^\\`"'\n]+\\[^\\`"'\n]+\\Muhammad-Attique-Calculator/gi, 'Muhammad-Attique-Calculator');
  res = res.replace(/[A-Za-z]:\/[^\/`"'\n]+\/[^\/`"'\n]+\/Muhammad-Attique-Calculator/gi, 'Muhammad-Attique-Calculator');

  return res;
}

async function run() {
  // 1. Copy raw file
  const rawLog = fs.readFileSync(srcLogPath, 'utf8');
  // Sanitize the JSONL content for user privacy
  const sanitizedJsonl = sanitizeText(rawLog);
  fs.writeFileSync(destJsonlPath, sanitizedJsonl, 'utf8');

  // 2. Build Markdown
  const lines = rawLog.split('\n');
  let out = '# Session Transcript: Pakistan Income Tax Calculator Web App\n\n';
  out += '**Session ID:** `619e8df5-7bcd-426d-acbe-1db8269aaa53`  \n';
  out += '**AI Tool:** Antigravity (Google DeepMind)  \n';
  out += '**Model:** Gemini 3.8 Flash  \n\n---\n\n';

  for (const line of lines) {
    if (!line.trim()) continue;
    try {
      const data = JSON.parse(line);
      if (data.type === 'USER_INPUT' && data.content) {
        let clean = data.content;
        const match = clean.match(/<USER_REQUEST>([\s\S]*?)<\/USER_REQUEST>/);
        if (match) {
          clean = match[1].trim();
        } else {
          clean = clean
            .replace(/<ADDITIONAL_METADATA>[\s\S]*?<\/ADDITIONAL_METADATA>/g, '')
            .replace(/<USER_SETTINGS_CHANGE>[\s\S]*?<\/USER_SETTINGS_CHANGE>/g, '')
            .trim();
        }
        if (clean) {
          out += `## User\n\n${sanitizeText(clean)}\n\n---\n\n`;
        }
      } else if (data.type === 'PLANNER_RESPONSE' && data.content) {
        out += `## Assistant\n\n${sanitizeText(data.content.trim())}\n\n---\n\n`;
      }
    } catch (e) {}
  }

  fs.writeFileSync(destMdPath, out, 'utf8');
  console.log('Both session-01.md and transcript_full.jsonl updated and sanitized successfully!');
}

run();
